package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

// AmtRec 01 AMT-REC, 11 bytes
type AmtRec struct {
	ArAcct string          // PIC X(4) @0 len=4
	ArAmt  decimal.Decimal // PIC 9(5)V99 @4 len=7
}

var WsEofFlag string // PIC X len=1 = "N"
var WsBigTotal decimal.Decimal
var WsWrapTotal decimal.Decimal
var WsSafeTotal decimal.Decimal
var WsOverflows int64
var WsCount int64
var WsHalf decimal.Decimal
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var arRec AmtRec
var inputDone bool

// helpers for PIC storage with high-order truncation
func intPow10(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func decimalPow10(n int) decimal.Decimal {
	return decimal.New(1, int32(n))
}

// storePIC truncates toward zero to scale and drops high-order integer digits
func storePIC(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	// truncate toward zero to scale
	t := v.Truncate(int32(scale))
	// scaled integer (toward zero)
	scaled := t.Shift(int32(scale)).Truncate(0)
	// modulus 10^(intDigits+scale) for positive numbers
	// for negative we need to keep sign and mod magnitude
	mod := decimalPow10(intDigits + scale)
	// decimal Mod for negative: we want to keep low order digits of magnitude
	// COBOL drops high digits, sign preserved. For positive simple Mod.
	if scaled.IsNegative() {
		neg := true
		_ = neg
		// magnitude mod
		mag := scaled.Abs()
		m := mag.Mod(mod)
		// reapply sign
		m = m.Neg()
		return m.Shift(int32(-scale))
	}
	m := scaled.Mod(mod)
	return m.Shift(int32(-scale))
}

// format for edited pictures like ZZ,ZZ9.99 and ZZ,ZZ9.9
func formatEdited(v decimal.Decimal, picture string) string {
	// count scale = decimal digits after '.'
	dotIdx := strings.Index(picture, ".")
	scale := 0
	if dotIdx >= 0 {
		scale = len(picture) - dotIdx - 1
	}
	intPicPart := picture
	if dotIdx >= 0 {
		intPicPart = picture[:dotIdx]
	}
	// number of integer digit positions = count of Z and 9 before dot
	intDigits := 0
	for _, ch := range intPicPart {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	// truncate value to scale toward zero (COBOL move truncates)
	t := v.Truncate(int32(scale))
	if t.IsNegative() {
		t = t.Abs()
	}
	// drop high order digits beyond picture integer capacity
	// high-order drop is defined for numeric-edited move as well
	modPow := intPow10(intDigits)
	// we need integer part after truncation
	// compute scaled integer
	scaled := t.Shift(int32(scale)).Truncate(0)
	// integer part
	intPartDec := scaled.Div(decimalPow10(scale)).Truncate(0)
	// frac part
	fracPartDec := scaled.Abs().Mod(decimalPow10(scale)).Abs()

	// int part high-order drop
	intPartDec = intPartDec.Mod(decimal.New(intPow10(intDigits), 0))

	intPart := intPartDec.IntPart() // fits in intDigits digits now
	fracPart := fracPartDec.IntPart()

	// build digit arrays
	intDigitsArr := make([]int, intDigits)
	tmp := intPart
	for i := intDigits - 1; i >= 0; i-- {
		intDigitsArr[i] = int(tmp % 10)
		tmp /= 10
	}
	fracDigitsArr := make([]int, scale)
	tmp = fracPart
	for i := scale - 1; i >= 0; i-- {
		fracDigitsArr[i] = int(tmp % 10)
		tmp /= 10
	}

	// build result as runes of picture length
	res := []rune(picture)

	// map integer digit positions indices in res
	intPosIdx := []int{}
	for i, ch := range res {
		if ch == 'Z' || ch == '9' {
			// only count those before dot
			if dotIdx >= 0 && i > dotIdx {
				continue
			}
			if dotIdx < 0 {
				// no dot
			}
			intPosIdx = append(intPosIdx, i)
		}
	}
	// dotIdx distinguishes; but frac positions are after dot
	fracPosIdx := []int{}
	if dotIdx >= 0 {
		for i, ch := range res {
			if (ch == 'Z' || ch == '9') && i > dotIdx {
				fracPosIdx = append(fracPosIdx, i)
			}
		}
	}

	// fill integer digits
	for idx, pos := range intPosIdx {
		d := intDigitsArr[idx]
		res[pos] = rune('0' + d)
	}
	// fill frac digits
	for idx, pos := range fracPosIdx {
		d := 0
		if idx < len(fracDigitsArr) {
			d = fracDigitsArr[idx]
		}
		res[pos] = rune('0' + d)
	}

	// Z suppression
	// find first non-zero integer digit index in intDigitsArr
	firstNonZero := -1
	for i, d := range intDigitsArr {
		if d != 0 {
			firstNonZero = i
			break
		}
	}
	// if all zero, firstNonZero stays -1 -> suppress all Z's before last position
	// suppression applies to Z positions with idx < effective cutoff
	cutoff := len(intPosIdx) // exclusive
	if firstNonZero == -1 {
		// keep only the last mandatory 9 position (the last intPos)
		// cutoff is last index
		cutoff = len(intPosIdx) - 1
	} else {
		cutoff = firstNonZero
	}
	// blank Z positions where idx < cutoff
	for idx, pos := range intPosIdx {
		picCh := rune(picture[pos])
		if picCh == 'Z' && idx < cutoff {
			res[pos] = ' '
		}
	}
	// commas inside suppressed zone become spaces
	// suppressed zone is from left to just before first non-suppressed digit position in terms of picture index
	if len(intPosIdx) > 0 {
		var firstKeptPos int
		if cutoff < len(intPosIdx) {
			firstKeptPos = intPosIdx[cutoff]
		} else {
			// shouldn't happen, fallback to dot
			if dotIdx >= 0 {
				firstKeptPos = dotIdx
			} else {
				firstKeptPos = len(res)
			}
		}
		for i, ch := range res {
			if ch == ',' && i < firstKeptPos {
				res[i] = ' '
			}
		}
	}

	return string(res)
}

func formatPIC99(v int64, digits int) string {
	// zero padded to digits, high order truncated
	mod := intPow10(digits)
	// handle negative not needed
	if v < 0 {
		v = -v
	}
	v = v % mod
	return fmt.Sprintf("%0*d", digits, v)
}

func addWithSizeError(target *decimal.Decimal, addend decimal.Decimal, intDigits int, scale int) bool {
	sum := target.Add(addend)
	// check overflow: does sum fit in PIC 9(intDigits)Vscale ?
	// truncate sum to scale then compare magnitude
	trunc := sum.Truncate(int32(scale))
	// For positive, overflow if trunc >= 10^intDigits
	limit := decimalPow10(intDigits) // 100000 for 5 digits
	// Negative would be <0 but amounts are positive
	if trunc.Cmp(limit) >= 0 || trunc.Cmp(decimal.Zero) < 0 {
		return true
	}
	// Also need to check fractional overflow? No, fractional always fits after truncation
	*target = storePIC(sum, intDigits, scale)
	return false
}

// paragraph functions
func ReadPara(reader *bufio.Reader) bool {
	// This is replaced by scanner loop; kept for structure
	return false
}

func OverflowPara() {
	WsOverflows = storeInt(WsOverflows+1, 2)
}

func storeInt(v int64, digits int) int64 {
	mod := intPow10(digits)
	return v % mod
}

func MainPara() {
	// open input.dat
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	// allow long lines
	var lines []string
	for scanner.Scan() {
		line := scanner.Text()
		// scanner strips newline, we keep line as is (spaces preserved except trailing? scanner keeps)
		lines = append(lines, line)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read input: %v\n", err)
		os.Exit(1)
	}

	// state
	WsEofFlag = "N"
	inputDone = false
	WsBigTotal = decimal.New(0, 0)
	WsWrapTotal = decimal.New(0, 0)
	WsSafeTotal = decimal.New(0, 0)
	WsOverflows = 0
	WsCount = 0
	WsHalf = decimal.New(0, 0)

	idx := 0
	var currentRec *AmtRec
	var hasRec bool

	// PERFORM READ-PARA
	readNext := func() {
		if idx >= len(lines) {
			WsEofFlag = "Y"
			inputDone = true
			hasRec = false
			return
		}
		raw := lines[idx]
		idx++
		// pad to 11 with spaces
		if len(raw) < 11 {
			raw = raw + strings.Repeat(" ", 11-len(raw))
		}
		if len(raw) > 11 {
			raw = raw[:11]
		}
		acct := raw[0:4]
		amtStr := raw[4:11]
		// parse amtStr digits only (may contain spaces? treat spaces as 0? but assume digits)
		amtStrTrim := strings.TrimSpace(amtStr)
		// If amtStr contains spaces due to padding, treat as zeros? Cobol would have spaces -> ambiguous.
		// We'll parse digits ignoring spaces.
		digitsOnly := ""
		for _, ch := range amtStr {
			if ch >= '0' && ch <= '9' {
				digitsOnly += string(ch)
			}
		}
		if digitsOnly == "" {
			digitsOnly = "0"
		}
		// amtStr len 7 = 5 int +2 frac
		// parse as integer then shift -2
		// digitsOnly may be shorter due to spaces; pad left with zeros to 7?
		// Use integer value of digitsOnly with appropriate scale:
		// If original had 7 chars all digits, digitsOnly length 7 -> shift -2
		// If shorter, we treat missing leading zeros? Simpler: parse digitsOnly as integer with shift -2 but if digitsOnly length <7, we still shift -2? Actually if line shorter, the field might be truncated, but spec says pad with spaces, so missing digits become spaces -> should be considered 0? We'll just parse digitsOnly as integer and if len <7 we still need to interpret as if leading spaces were zeros? But truncated line means field missing entirely -> treat as 0.
		// We'll pad digitsOnly to 7 left with zeros before converting? No, that would misplace.
		// Approach: take raw amt part (7 chars) replace spaces with '0' then parse 7-digit integer shift -2
		amtRaw7 := raw[4:11]
		clean := ""
		for _, ch := range amtRaw7 {
			if ch >= '0' && ch <= '9' {
				clean += string(ch)
			} else {
				clean += "0"
			}
		}
		// handle case amtStrTrim == "" -> clean is "0000000"
		_ = amtStrTrim
		decInt := decimal.RequireFromString(clean)
		amtDec := decInt.Shift(-2)

		currentRec = &AmtRec{ArAcct: acct, ArAmt: amtDec}
		hasRec = true
		WsEofFlag = "N"
		inputDone = false
	}

	readNext() // initial READ

	// PERFORM PROCESS-PARA UNTIL INPUT-DONE
	for !inputDone {
		// PROCESS-PARA
		if hasRec {
			arRec = *currentRec

			// ADD AR-AMT TO WS-BIG-TOTAL (with wrap)
			sumBig := WsBigTotal.Add(arRec.ArAmt)
			WsBigTotal = storePIC(sumBig, 7, 2)

			// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL (drop high digits)
			WsWrapTotal = storePIC(WsBigTotal, 5, 2)

			// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA
			overflowed := addWithSizeError(&WsSafeTotal, arRec.ArAmt, 5, 2)
			if overflowed {
				OverflowPara()
			}

			// ADD 1 TO WS-COUNT
			WsCount = storeInt(WsCount+1, 2)

			// COMPUTE WS-HALF = AR-AMT / 2  (no rounded -> truncated)
			// Use decimal division then truncate to scale 1
			halfRaw := arRec.ArAmt.Div(decimal.NewFromInt(2))
			WsHalf = storePIC(halfRaw, 5, 1)

			// MOVEs to edited
			WsAmtEd = formatEdited(arRec.ArAmt, "ZZ,ZZ9.99")
			WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
			WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
			WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")

			// DISPLAY
			fmt.Printf("%s %s %s %s %s\n", arRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
		}
		// PERFORM READ-PARA
		readNext()
	}

	// PERFORM SUMMARY-PARA
	fmt.Printf("RECORDS: %s\n", formatPIC99(WsCount, 2))
	fmt.Printf("OVERFLOWS: %s\n", formatPIC99(WsOverflows, 2))
}

func main() {
	MainPara()
}

